INSERT INTO setting (id, type, value, note) VALUES ('hellgao.lore', 'list', '', 'Lore fragments, one per clear, in this order, as id|text.');
INSERT INTO setting_item (setting_id, position, value) VALUES ('hellgao.lore', 0, 'first_breath|Aethelgard breathed once, and the Devourer breathed with it. Between the two breaths, something listened.');
INSERT INTO setting_item (setting_id, position, value) VALUES ('hellgao.lore', 1, 'borrowed_faces|It has no face of its own. It wears the faces the Vocations left behind.');
INSERT INTO setting_item (setting_id, position, value) VALUES ('hellgao.lore', 2, 'the_count|The old Guardians counted the pulses. Hell Gao counts the silences.');
INSERT INTO setting_item (setting_id, position, value) VALUES ('hellgao.lore', 3, 'two_memories|Two memories collided and neither won. What stayed is not a god, not a beast, not an echo.');
INSERT INTO setting_item (setting_id, position, value) VALUES ('hellgao.lore', 4, 'no_name|The villagers cannot name it. They say "Hell Gao" and look at the sky between two stars.');
INSERT INTO setting_item (setting_id, position, value) VALUES ('hellgao.lore', 5, 'what_it_wants|It does not want your world. It wants the moment you stop and ask what comes after the end.');
INSERT INTO setting_item (setting_id, position, value) VALUES ('hellgao.lore', 6, 'the_last_pulse|When the pulse stops, you hear it for the first time: your own.');
